// Match the phone and desktop section CSS without a layout measurement. Shared
// by scheduled polls and store-driven reads so both respect hidden pages.
export function isComponentOffPage(owner) {
  if (!owner || typeof owner.closest !== 'function' || typeof document === 'undefined') return false;
  const body = document.body;
  if (!body?.classList?.contains('layout-basic') || typeof matchMedia !== 'function') return false;
  const phone = matchMedia('(max-width: 1099px)').matches;
  const page = phone ? body.dataset.mobilePage : body.dataset.desktopPage;
  if (!page) return false;
  if (!phone) {
    const slide = owner.closest('[data-info-slide]');
    if (slide && slide.getAttribute('data-info-slide') !== (body.dataset.desktopInfo || 'quests')) return true;
  }
  const attribute = phone ? 'data-mpage' : 'data-dpage';
  for (let host = owner.closest(`[${attribute}]`); host; host = host.parentElement?.closest(`[${attribute}]`)) {
    if (!String(host.getAttribute(attribute) || '').split(/\s+/).includes(page)) return true;
  }
  return false;
}
